#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Témafűzés (threading): közös szobában al-témák külön ágon,
hogy ne akadjon össze 5 párhuzamos vita.

Ez a modul a threading funkcionalitást valósítja meg az A2A Mesh rendszerhez.
Lehetővé teszi, hogy egy közös szobában több al-téma (thread) külön ágon
folyjon, így a párhuzamos viták nem keverednek össze.

Futtatható önálló demo módban a repó gyökeréből:
    python threading_manager.py
"""

import json
import time
import uuid
import hashlib
import threading
from dataclasses import dataclass, field, asdict
from enum import Enum
from typing import Dict, List, Optional, Set, Callable, Any
from collections import defaultdict


# ---------------------------------------------------------------------------
# Adatszerkezetek
# ---------------------------------------------------------------------------

class ThreadStatus(Enum):
    ACTIVE = "active"
    PAUSED = "paused"
    CLOSED = "closed"
    MERGED = "merged"


@dataclass
class ThreadedMessage:
    """Egy üzenet, ami egy konkrét thread-hez tartozik."""
    id: str
    room_id: str
    thread_id: str
    sender: str
    content: str
    parent_id: Optional[str] = None
    timestamp: float = field(default_factory=time.time)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict) -> "ThreadedMessage":
        return cls(**d)


@dataclass
class Thread:
    """Egy al-téma (thread) egy szobán belül."""
    id: str
    room_id: str
    title: str
    root_message_id: Optional[str] = None
    status: ThreadStatus = ThreadStatus.ACTIVE
    created_at: float = field(default_factory=time.time)
    last_activity: float = field(default_factory=time.time)
    message_ids: List[str] = field(default_factory=list)
    participants: Set[str] = field(default_factory=set)
    parent_thread_id: Optional[str] = None  # nested threading
    tags: List[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        d = asdict(self)
        d["status"] = self.status.value
        d["participants"] = list(self.participants)
        return d

    @classmethod
    def from_dict(cls, d: dict) -> "Thread":
        d = dict(d)
        d["status"] = ThreadStatus(d.get("status", "active"))
        d["participants"] = set(d.get("participants", []))
        return cls(**d)


# ---------------------------------------------------------------------------
# Thread Manager
# ---------------------------------------------------------------------------

class ThreadManager:
    """
    Központi manager, ami szobánként kezeli a thread-eket.
    Szálbiztos (thread-safe) implementáció.
    """

    def __init__(self, max_threads_per_room: int = 20, auto_close_idle_seconds: float = 3600):
        self._lock = threading.RLock()
        self._threads: Dict[str, Thread] = {}              # thread_id -> Thread
        self._messages: Dict[str, ThreadedMessage] = {}     # message_id -> ThreadedMessage
        self._room_threads: Dict[str, Set[str]] = defaultdict(set)  # room_id -> {thread_ids}
        self._default_thread: Dict[str, str] = {}           # room_id -> default thread_id
        self._max_threads_per_room = max_threads_per_room
        self._auto_close_idle_seconds = auto_close_idle_seconds
        self._listeners: List[Callable[[ThreadedMessage], None]] = []

    # -- Listener support ---------------------------------------------------

    def add_listener(self, callback: Callable[[ThreadedMessage], None]):
        """Üzenet érkezéskor meghívandó callback regisztrálása."""
        with self._lock:
            self._listeners.append(callback)

    def _notify_listeners(self, msg: ThreadedMessage):
        for cb in self._listeners:
            try:
                cb(msg)
            except Exception:
                pass

    # -- Thread lifecycle ---------------------------------------------------

    def create_thread(
        self,
        room_id: str,
        title: str,
        parent_thread_id: Optional[str] = None,
        tags: Optional[List[str]] = None,
    ) -> Thread:
        """Új al-téma (thread) létrehozása egy szobában."""
        with self._lock:
            if len(self._room_threads.get(room_id, set())) >= self._max_threads_per_room:
                raise ValueError(
                    f"Maximum thread count ({self._max_threads_per_room}) "
                    f"reached for room '{room_id}'"
                )
            thread_id = f"thread_{uuid.uuid4().hex[:12]}"
            thread = Thread(
                id=thread_id,
                room_id=room_id,
                title=title,
                parent_thread_id=parent_thread_id,
                tags=tags or [],
            )
            self._threads[thread_id] = thread
            self._room_threads[room_id].add(thread_id)

            # Ha ez az első thread a szobában, legyen az alapértelmezett
            if room_id not in self._default_thread:
                self._default_thread[room_id] = thread_id

            return thread

    def get_or_create_default_thread(self, room_id: str) -> Thread:
        """Visszaadja vagy létrehozza a szoba alapértelmezett thread-jét."""
        with self._lock:
            if room_id in self._default_thread:
                t = self._threads.get(self._default_thread[room_id])
                if t:
                    return t
            return self.create_thread(room_id, "Fő szál (main)")

    def close_thread(self, thread_id: str) -> bool:
        """Thread lezárása — nem lehet többé üzenetet küldeni bele."""
        with self._lock:
            t = self._threads.get(thread_id)
            if not t:
                return False
            t.status = ThreadStatus.CLOSED
            return True

    def pause_thread(self, thread_id: str) -> bool:
        with self._lock:
            t = self._threads.get(thread_id)
            if not t:
                return False
            t.status = ThreadStatus.PAUSED
            return True

    def resume_thread(self, thread_id: str) -> bool:
        with self._lock:
            t = self._threads.get(thread_id)
            if not t:
                return False
            if t.status == ThreadStatus.PAUSED:
                t.status = ThreadStatus.ACTIVE
                return True
            return False

    def merge_thread(self, source_thread_id: str, target_thread_id: str) -> bool:
        """
        Egy thread összevonása egy másikkal.
        Az üzenetek átkerülnek a cél thread-be.
        """
        with self._lock:
            src = self._threads.get(source_thread_id)
            tgt = self._threads.get(target_thread_id)
            if not src or not tgt:
                return False
            if src.room_id != tgt.room_id:
                return False
            for mid in src.message_ids:
                msg = self._messages.get(mid)
                if msg:
                    msg.thread_id = target_thread_id
                    tgt.message_ids.append(mid)
                    tgt.participants.add(msg.sender)
            src.status = ThreadStatus.MERGED
            tgt.last_activity = time.time()
            return True

    def auto_close_idle_threads(self) -> List[str]:
        """Automatikusan lezárja az inaktív thread-eket."""
        closed = []
        with self._lock:
            now = time.time()
            for tid, t in self._threads.items():
                if t.status != ThreadStatus.ACTIVE:
                    continue
                if now - t.last_activity > self._auto_close_idle_seconds:
                    t.status = ThreadStatus.CLOSED
                    closed.append(tid)
        return closed

    # -- Messaging ----------------------------------------------------------

    def post_message(
        self,
        room_id: str,
        sender: str,
        content: str,
        thread_id: Optional[str] = None,
        parent_id: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> ThreadedMessage:
        """
        Üzenet küldése egy szobába, egy konkrét thread-be.
        Ha nincs thread_id megadva, az alapértelmezett thread-be kerül.
        """
        with self._lock:
            # Thread meghatározása
            if thread_id is None:
                thread = self.get_or_create_default_thread(room_id)
                thread_id = thread.id
            else:
                thread = self._threads.get(thread_id)
                if not thread:
                    raise ValueError(f"Thread '{thread_id}' not found")
                if thread.room_id != room_id:
                    raise ValueError(
                        f"Thread '{thread_id}' does not belong to room '{room_id}'"
                    )
                if thread.status in (ThreadStatus.CLOSED, ThreadStatus.MERGED):
                    raise ValueError(
                        f"Thread '{thread_id}' is {thread.status.value}, "
                        f"cannot post messages"
                    )

            # Parent validáció
            if parent_id:
                parent = self._messages.get(parent_id)
                if not parent:
                    raise ValueError(f"Parent message '{parent_id}' not found")
                if parent.thread_id != thread_id:
                    raise ValueError(
                        f"Parent message belongs to thread '{parent.thread_id}', "
                        f"not '{thread_id}'"
                    )

            msg_id = f"msg_{uuid.uuid4().hex[:16]}"
            msg = ThreadedMessage(
                id=msg_id,
                room_id=room_id,
                thread_id=thread_id,
                sender=sender,
                content=content,
                parent_id=parent_id,
                metadata=metadata or {},
            )

            self._messages[msg_id] = msg
            thread.message_ids.append(msg_id)
            thread.participants.add(sender)
            thread.last_activity = time.time()

            # Root message beállítása, ha ez az első
            if thread.root_message_id is None:
                thread.root_message_id = msg_id

        self._notify_listeners(msg)
        return msg

    # -- Querying -----------------------------------------------------------

    def get_thread(self, thread_id: str) -> Optional[Thread]:
        with self._lock:
            return self._threads.get(thread_id)

    def get_room_threads(self, room_id: str, include_closed: bool = False) -> List[Thread]:
        with self._lock:
            tids = self._room_threads.get(room_id, set())
            result = []
            for tid in tids:
                t = self._threads.get(tid)
                if t and (include_closed or t.status not in (ThreadStatus.CLOSED, ThreadStatus.MERGED)):
                    result.append(t)
            result.sort(key=lambda x: x.last_activity, reverse=True)
            return result

    def get_thread_messages(self, thread_id: str, chronological: bool = True) -> List[ThreadedMessage]:
        with self._lock:
            t = self._threads.get(thread_id)
            if not t:
                return []
            msgs = [self._messages[mid] for mid in t.message_ids if mid in self._messages]
            msgs.sort(key=lambda m: m.timestamp, reverse=not chronological)
            return msgs

    def get_message(self, message_id: str) -> Optional[ThreadedMessage]:
        with self._lock:
            return self._messages.get(message_id)

    def get_thread_tree(self, thread_id: str) -> Dict[str, Any]:
        """
        Visszaadja a thread üzeneteit fa struktúrában (parent-child).
        """
        with self._lock:
            t = self._threads.get(thread_id)
            if not t:
                return {}
            msgs = self.get_thread_messages(thread_id)
            nodes = {}
            roots = []
            for m in msgs:
                nodes[m.id] = {"message": m.to_dict(), "children": []}
            for m in msgs:
                if m.parent_id and m.parent_id in nodes:
                    nodes[m.parent_id]["children"].append(nodes[m.id])
                else:
                    roots.append(nodes[m.id])
            return {
                "thread": t.to_dict(),
                "roots": roots,
            }

    def get_room_overview(self, room_id: str) -> Dict[str, Any]:
        """Összefoglaló nézet egy szoba összes thread-jéről."""
        with self._lock:
            threads = self.get_room_threads(room_id, include_closed=True)
            return {
                "room_id": room_id,
                "total_threads": len(threads),
                "active_threads": sum(1 for t in threads if t.status == ThreadStatus.ACTIVE),
                "threads": [
                    {
                        "id": t.id,
                        "title": t.title,
                        "status": t.status.value,
                        "message_count": len(t.message_ids),
                        "participants": list(t.participants),
                        "last_activity": t.last_activity,
                        "tags": t.tags,
                    }
                    for t in threads
                ],
            }

    # -- Serialization ------------------------------------------------------

    def export_state(self) -> dict:
        with self._lock:
            return {
                "threads": {tid: t.to_dict() for tid, t in self._threads.items()},
                "messages": {mid: m.to_dict() for mid, m in self._messages.items()},
                "room_threads": {rid: list(tids) for rid, tids in self._room_threads.items()},
                "default_thread": dict(self._default_thread),
            }

    def import_state(self, state: dict):
        with self._lock:
            self._threads = {
                tid: Thread.from_dict(td) for tid, td in state.get("threads", {}).items()
            }
            self._messages = {
                mid: ThreadedMessage.from_dict(md) for mid, md in state.get("messages", {}).items()
            }
            self._room_threads = defaultdict(set)
            for rid, tids in state.get("room_threads", {}).items():
                self._room_threads[rid] = set(tids)
            self._default_thread = dict(state.get("default_thread", {}))


# ---------------------------------------------------------------------------
# ThreadedRoom: kényelmi wrapper egyetlen szobára
# ---------------------------------------------------------------------------

class ThreadedRoom:
    """
    Kényelmi osztály egyetlen szoba kezelésére a ThreadManager felett.
    """

    def __init__(self, room_id: str, manager: Optional[ThreadManager] = None):
        self.room_id = room_id
        self.manager = manager or ThreadManager()
        # Alapértelmezett fő szál
        self.manager.get_or_create_default_thread(room_id)

    def new_topic(self, title: str, tags: Optional[List[str]] = None) -> Thread:
        """Új al-téma nyitása a szobában."""
        return self.manager.create_thread(self.room_id, title, tags=tags)

    def reply(self, sender: str, content: str, thread_id: Optional[str] = None,
              parent_id: Optional[str] = None) -> ThreadedMessage:
        """Válasz egy thread-ben."""
        return self.manager.post_message(
            self.room_id, sender, content, thread_id=thread_id, parent_id=parent_id
        )

    def list_topics(self, include_closed: bool = False) -> List[Thread]:
        return self.manager.get_room_threads(self.room_id, include_closed)

    def get_topic_messages(self, thread_id: str) -> List[ThreadedMessage]:
        return self.manager.get_thread_messages(thread_id)

    def overview(self) -> dict:
        return self.manager.get_room_overview(self.room_id)

    def close_topic(self, thread_id: str) -> bool:
        return self.manager.close_thread(thread_id)

    def merge_topic(self, source: str, target: str) -> bool:
        return self.manager.merge_thread(source, target)


# ---------------------------------------------------------------------------
# Demo / CLI
# ---------------------------------------------------------------------------

def _print_separator(title: str = "", char: str = "=", width: int = 70):
    if title:
        print(f"\n{char * 3} {title} {'' * (width - len(title) - 5)}")
    else:
        print(char * width)


def _print_thread_tree(node: dict, indent: int = 0):
    msg = node["message"]
    prefix = "  " * indent + ("├─ " if indent > 0 else "")
    print(f"{prefix}[{msg['sender']}] {msg['content'][:60]}")
    for child in node["children"]:
        _print_thread_tree(child, indent + 1)


def run_demo():
    """Bemutató: 5 párhuzamos vita egy szobában, külön thread-eken."""
    print("=" * 70)
    print("A2A Mesh — Témafűzés (threading) demo")
    print("5 párhuzamos vita külön ágon, közös szobában")
    print("=" * 70)

    manager = ThreadManager(max_threads_per_room=50)
    room = ThreadedRoom("debate_room_1", manager)

    # Listener: log minden üzenetet
    def logger(msg: ThreadedMessage):
        t = manager.get_thread(msg.thread_id)
        title = t.title if t else "???"
        print(f"  [LOG] ({title}) {msg.sender}: {msg.content[:50]}...")

    manager.add_listener(logger)

    # --- 5 párhuzamos téma nyitása ---
    _print_separator("5 téma nyitása")

    topics = [
        ("Threading architektúra", ["arch", "design"]),
        ("Token-tömörítés stratégiája", ["perf", "context"]),
        ("Duplikátum-szűrő algoritmus", ["dedup", "quality"]),
        ("Agent-profil formátum", ["agents", "metadata"]),
        ("Broadcast protokoll", ["network", "protocol"]),
    ]

    thread_ids = []
    for title, tags in topics:
        t = room.new_topic(title, tags=tags)
        thread_ids.append(t.id)
        print(f"  ✓ Téma nyitva: '{title}' -> {t.id}")

    # --- Üzenetek küldése különböző thread-ekbe ---
    _print_separator("Üzenetek küldése különböző ágakba")

    # Thread 0: Threading architektúra
    m1 = room.reply("mano", "A thread-ek fa struktúrában legyenek, parent-child relációval.", thread_ids[0])
    m2 = room.reply("runa", "Egyetértek, de figyelni kell a mélységet — max 3-4 szint.", thread_ids[0], parent_id=m1.id)
    room.reply("mano", "Jó ötlet, limitáljuk a nesting-et.", thread_ids[0], parent_id=m2.id)

    # Thread 1: Token-tömörítés
    room.reply("agent_alpha", "Ha >4000 token, automatikus összefoglaló.", thread_ids[1])
    room.reply("agent_beta", "MapReduce stílusú összefoglalás? Vagy sliding window?", thread_ids[1])

    # Thread 2: Duplikátum-szűrő
    room.reply("mano", "Cosine similarity a bejövő üzeneteken, threshold 0.85.", thread_ids[2])
    room.reply("runa", "Jaccard is működhet, és gyorsabb nagy corpusnál.", thread_ids[2])

    # Thread 3: Agent-profilok
    room.reply("agent_gamma", "JSON schema: name, capabilities, preferences, history_hash.", thread_ids[3])

    # Thread 4: Broadcast protokoll
    room.reply("agent_delta", "Gossip protocol vs. centralized broker?", thread_ids[4])
    room.reply("agent_alpha", "Gossip skálázódik jobban, de eventual consistency.", thread_ids[4])

    # --- Szoba áttekintés ---
    _print_separator("Szoba áttekintés")
    overview = room.overview()
    print(json.dumps(overview, indent=2, ensure_ascii=False))

    # --- Thread fa struktúra (thread 0) ---
    _print_separator("Thread fa struktúra: 'Threading architektúra'")
    tree = manager.get_thread_tree(thread_ids[0])
    for root in tree["roots"]:
        _print_thread_tree(root)

    # --- Thread lezárása és merge ---
    _print_separator("Thread lezárás + merge demo")
    print(f"  Lezárás: {room.close_topic(thread_ids[3])}")
    print(f"  Merge ({thread_ids[2]} -> {thread_ids[0]}): {room.merge_topic(thread_ids[2], thread_ids[0])}")

    # --- Export/import ---
    _print_separator("State export/import")
    state = manager.export_state()
    print(f"  Exportált thread-ek: {len(state['threads'])}")
    print(f"  Exportált üzenetek: {len(state['messages'])}")

    manager2 = ThreadManager()
    manager2.import_state(state)
    restored = manager2.get_room_threads("debate_room_1", include_closed=True)
    print(f"  Importált thread-ek: {len(restored)}")

    # --- Próba: üzenet lezárt thread-be ---
    _print_separator("Hiba kezelés: lezárt thread-be küldés")
    try:
        room.reply("mano", "Ez nem sikerülhet.", thread_id=thread_ids[3])
    except ValueError as e:
        print(f"  ✓ Elvártnak megfelelő hiba: {e}")

    # --- Auto-close idle ---
    _print_separator("Auto-close idle threads (0s threshold demo)")
    manager._auto_close_idle_seconds = 0.0
    closed = manager.auto_close_idle_threads()
    print(f"  Auto-closed thread-ek: {closed}")

    _print_separator("Demo vége")
    print("✓ A témafűzés funkcionalitás működik: 5 vita külön ágon,")
    print("  nem keveredtek össze, fa struktúra, merge, close, export/import OK.")


if __name__ == "__main__":
    run_demo()